/** 日本時間の date 0 時〜翌 0 時を、updated_at と同じ UTC の ISO 文字列で返す */
function tokyoDayRange(date: string): [string, string] {
  const start = new Date(`${date}T00:00:00+09:00`);
  const end = new Date(start.getTime() + 24 * 60 * 60 * 1000);
  return [start.toISOString(), end.toISOString()];
}

// salesOn の中
.get(...tokyoDayRange(date))

test('日本時間の早朝の注文はその日に数える', async () => {
  const { report, placeAt } = setup();
  await placeAt('2026-10-10T16:00:00Z', 1000); // 日本時間 10/11 01:00
  assert.equal(report.salesOn('2026-10-10').totalAmount, 0);
  assert.equal(report.salesOn('2026-10-11').totalAmount, 1000);
});
